namespace Target;
public static class ToolInputPolicy
{
    public static bool IsSafeInput(string fileName)
    {
        if (string.IsNullOrEmpty(fileName) || fileName is "." or "..")
        {
            return false;
        }

        foreach (var character in fileName)
        {
            if (!char.IsAsciiLetterOrDigit(character) && character is not '.' and not '_' and not '-')
            {
                return false;
            }
        }

        return true;
    }
}
